sys_script.script:
(function executeRule(current, previous) {
    var startDate = current.getValue('start_date');
    var endDate = current.getValue('end_date');
    if (!startDate || !endDate) return;

    var start = new GlideDateTime(startDate + ' 00:00:00');
    var end = new GlideDateTime(endDate + ' 00:00:00');

    if (end.compareTo(start) < 0) {
        gs.addErrorMessage('End date must be on or after start date.');
        current.setAbortAction(true);
        return;
    }

    // Get weekend days from attendance config
    var weekendDays = 'saturday,sunday';
    var cfgGr = new GlideRecord('x_2316161_bjit_e_0_att_cfg');
    cfgGr.addQuery('active', true);
    cfgGr.setLimit(1);
    cfgGr.query();
    if (cfgGr.next()) {
        weekendDays = cfgGr.getValue('weekend_days') || 'saturday,sunday';
    }
    var weekends = weekendDays.toLowerCase().split(',');

    // Get holidays
    var holidays = {};
    var holGr = new GlideRecord('x_2316161_bjit_e_0_holiday');
    holGr.addQuery('active', true);
    holGr.query();
    while (holGr.next()) {
        holidays[holGr.getValue('date')] = true;
    }

    var dayNames = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
    var count = 0;
    var current_dt = new GlideDateTime(start);
    var endCheck = new GlideDateTime(end);
    endCheck.addDaysLocalTime(1);

    while (current_dt.compareTo(endCheck) < 0) {
        var dayOfWeek = current_dt.getDayOfWeekLocalTime();
        var dayName = dayNames[dayOfWeek - 1];
        var dateStr = current_dt.getDate().toString();

        var isWeekend = false;
        for (var w = 0; w < weekends.length; w++) {
            if (weekends[w].trim() === dayName) { isWeekend = true; break; }
        }

        if (!isWeekend && !holidays[dateStr]) {
            count++;
        }
        current_dt.addDaysLocalTime(1);
    }

    current.setValue('duration', count);
})(current, previous);
